let lang=localStorage.getItem('triibe-language')||'en',step=1,quizStep=0,answers=[],recommendation='';let draft={};try{draft=JSON.parse(localStorage.getItem('triibe-draft')||'{}')}catch{}const t=(en,zh)=>lang==='en'?en:zh;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const app=document.getElementById('app');
function render(){document.documentElement.lang=lang==='en'?'en':'zh-CN';app.innerHTML=`
<div class="notice">${t('Student concept · Proposed TRIIBE × Shanghai United Foundation collaboration · Not an official joint website','学生概念原型 · TRIIBE × 上海联劝公益基金会拟议合作 · 非双方官方联合网站')}</div><header><a class="brand" href="#">TRIIBE <small>×</small> 联劝<span>THE NEXT STEP · 合作概念</span></a><button class="lang mobilemenu" id="menuToggle" aria-expanded="false">${t('Menu ☰','目录 ☰')}</button><nav id="mainNav" aria-label="${t('Main navigation','主导航')}">${[['home','Home','首页'],['support','Seed funding','种子资助'],['how','How it works','参与流程'],['stories','Explore ideas','探索灵感'],['partners','The collaboration','合作构想'],['faq','FAQs','常见问题'],['contact','Contact','联系我们']].map(([id,en,zh])=>`<a href="#${id}" data-nav="${id}">${t(en,zh)}</a>`).join('')}<button class="lang" id="language">${t('中文','EN')}</button><a class="pill" data-nav="apply" href="#apply">${t('Try an application ↗','体验申请 ↗')}</a></nav></header>
<main><div class="wrap"><div class="hero"><div><div class="eyebrow">${t('THE NEXT STEP / IMPACT SEED PROGRAM','THE NEXT STEP / 公益种子计划')}</div><h1>${t('Big change.<br>A <em>small</em><br>first step.','让改变，<br>从<em>一小步</em><br>开始。')}</h1><p class="lead">${t('An early idea. A local connection. Room to try. A proposed collaboration connecting young people in China with the support to take their first step.','一个早期想法，一次本地连接，一点尝试空间。探索 TRIIBE 与上海联劝公益基金会如何共同支持中国年轻人的公益第一步。')}</p><div class="actions"><a class="pill" href="#find">${t('Find your first step ↗','找到你的第一步 ↗')}</a><a class="pill outline" href="#how">${t('Explore the program','了解项目')}</a></div><p class="micro">${t('Designed for young people aged 18–25 in China.','面向中国 18–25 岁年轻人设计。')}</p></div><div class="art" role="img" aria-label="${t('An illustrated seedling growing from a small seed','从种子中生长出的幼苗插画')}"><div class="float">${t('An idea is a place to start.','一个想法，就可以是起点。')}</div><svg class="plant" viewBox="0 0 240 330" xmlns="http://www.w3.org/2000/svg"><ellipse cx="120" cy="300" rx="95" ry="12" fill="#b7c4a4"/><path d="M119 290C128 230 109 166 132 89" fill="none" stroke="#35533c" stroke-width="6"/><path d="M122 201C53 197 33 152 38 115C94 111 123 151 122 201Z" fill="#83965c"/><path d="M124 157C189 155 213 111 203 70C154 72 127 111 124 157Z" fill="#35533c"/><path d="M133 98C100 83 94 49 109 24C142 36 151 68 133 98Z" fill="#acbb76"/><path d="M121 273C90 247 78 263 82 287C86 318 133 322 156 295C176 272 145 247 121 273" fill="#b99b72"/><path d="M120 273Q111 287 125 306" stroke="#8e7553" fill="none" stroke-width="2"/></svg><span class="artlabel">${t('Start small. Grow with support.','从小处开始，在支持中生长。')}</span></div></div><div class="strip"><div><strong>18–25</strong><span>${t('PROPOSED AGE GROUP','计划服务年龄')}</span></div><div><strong>${t('1–2 months','1–2 个月')}</strong><span>${t('PROPOSED PILOT LENGTH','拟定试点周期')}</span></div><div><strong>${t('Your first experiment','你的第一次尝试')}</strong><span>${t('NO REGISTERED ORGANIZATION NEEDED TO EXPLORE','探索阶段无需已注册组织')}</span></div></div>
<section id="support"><div class="sectionhead"><div><div class="eyebrow">${t('A little support. Room to try.','一点支持，一次尝试的空间')}</div><h2>${t('You bring an idea.<br>Let’s work out the next step.','带着想法来，<br>一起找到下一步。')}</h2></div><p>${t('You may need a conversation before you need a budget. This proposed program combines different kinds of support around your starting point.','你可能先需要一次交流，再需要一笔预算。我们正在探索根据你的起点，组合不同支持的方式。')}</p></div><div class="cards">${[[t('01 / Guidance','01 / 导师指导'),t('Make the idea manageable','把想法变得可执行'),t('Work through who you want to help, what you need to learn, and a realistic first experiment.','梳理你想帮助谁、需要了解什么，以及第一次尝试应该多大。'),t('Scope your pilot|Plan a first conversation|Reflect on what you learn','明确试点范围|准备首次沟通|复盘试点收获')],[t('02 / Connections','02 / 本地连接'),t('Find people who know the context','找到了解当地的人'),t('Explore what a local nonprofit, university, or community group could help you do. Partnerships are still being researched.','探索本地公益机构、大学或社区组织可以提供的帮助。目前合作关系仍在研究中。'),t('Understand local needs|Identify potential collaborators|Explore access and permissions','了解本地需求|寻找潜在合作方|确认参与条件')],[t('03 / Seed support','03 / 种子支持'),t('Cover a practical first step','支持实际的第一步'),t('A proposed ¥1,000–5,000 range for small pilot expenses. Amounts, eligibility and funding availability are not confirmed.','拟探索 ¥1,000–5,000 的小额试点支持。金额、申请条件与资金来源尚未确定。'),t('Build a simple budget|Identify essential costs|Test before expanding','制定简单预算|识别必要支出|先测试，再扩大')]].map(c=>`<article class="card"><span class="eyebrow">${c[0]}</span><h3>${c[1]}</h3><p>${c[2]}</p><ul>${c[3].split('|').map(a=>`<li>${a}</li>`).join('')}</ul></article>`).join('')}</div><div class="actions"><a class="pill" href="#find">${t('Find the support I need ↗','找到我需要的支持 ↗')}</a><a class="pill outline" href="#how">${t('See the journey →','了解参与流程 →')}</a></div></section></div>
<section class="dark" id="how"><div class="wrap"><div class="eyebrow">${t('THE JOURNEY','参与路径')}</div><h2>${t('An experiment,<br>not a lifetime commitment.','一次尝试，<br>从可做到的事情开始。')}</h2><div class="steps">${[[t('Tell us your idea','说出你的想法'),t('Describe a community issue and what you would like to explore. An early idea is enough for this prototype.','描述一个你关心的问题，以及想探索的方向。测试申请可以从早期想法开始。')],[t('Shape a small pilot','设计小型试点'),t('Define one action, the people involved, and what you hope to learn.','明确一个行动、参与的人，以及你希望了解什么。')],[t('Match the support','匹配所需支持'),t('Explore guidance, local connections and a budget that fits your pilot.','探索导师、本地资源与适合试点的预算。')],[t('Try, learn, decide','尝试、学习、决定'),t('Run the experiment, reflect on the result, and decide what comes next.','开展试点、复盘结果，并决定下一步。')]].map((a,i)=>`<div class="step"><b>0${i+1}</b><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('')}</div><div class="actions"><a class="pill light" href="#apply">${t('Explore your idea ↗','开始探索你的想法 ↗')}</a></div><div class="outcomes">${t('Stop with learning|Refine the idea|Continue testing|Explore scaling','学习后暂停|调整想法|继续测试|探索扩大').split('|').map(s=>`<span>${s}</span>`).join('')}</div><p class="micro" style="color:#cbd7ca">${t('A useful outcome can be learning what to change, or deciding that an idea should stop.','有价值的结果也包括发现需要调整的地方，或决定不继续某个想法。')}</p></div></section>
<div class="wrap"><section id="find" class="split"><div><div class="eyebrow">${t('START WHERE YOU ARE','从你的现状出发')}</div><h2>${t('What would help<br>you start?','什么支持，<br>能帮你开始？')}</h2><p class="lead">${t('Three short questions to explore a possible first step. You can still choose a different kind of support in your application.','回答三个简短问题，探索适合你的第一步。你也可以在申请中选择其他支持。')}</p><p class="micro">${t('This guide suggests a starting point; it does not assess funding eligibility.','此工具提供起步建议，不用于评估资助资格。')}</p></div><div class="quiz" id="quiz"></div></section>
<section id="stories"><div class="eyebrow">${t('WHAT COULD A SMALL PILOT LOOK LIKE?','小型试点可以是什么样？')}</div><h2>${t('Keep the first version small.','让第一次尝试小一点。')}</h2><p class="micro">${t('Illustrative scenarios — not funded projects or reported outcomes.','以下为情境示例，并非已获资助的项目或真实成果。')}</p><div class="cards example">${[[t('Community connection','社区连接'),t('Listen before organizing','先倾听，再组织'),t('Talk with a local animal shelter to understand one practical need before planning a student activity.','先与当地动物收容所交流，了解一个实际需求，再策划学生活动。')],[t('A manageable test','可执行的小测试'),t('Try one repair session','试办一次修补活动'),t('Invite a few classmates to a clothing repair session and learn what tools and guidance they need.','邀请几位同学参加衣物修补活动，了解他们需要什么工具和指导。')],[t('Learning with others','共同学习'),t('Test one accessible resource','测试一份易用的资源'),t('Co-design a simple campus guide with intended users, then observe what they find useful or confusing.','与目标使用者共同设计一份校园指南，再观察哪些内容有用、哪些不清楚。')]].map(a=>`<article class="card"><span class="tag">${a[0]}</span><h3><strong>${a[1]}</strong></h3><p>${a[2]}</p></article>`).join('')}</div></section></div>
<section class="formarea" id="apply"><div class="wrap split"><div><div class="eyebrow">${t('YOUR IDEA STARTS HERE','从你的想法开始')}</div><h2>${t('Tell us what<br>you want to try.','说说你<br>想尝试什么。')}</h2><p>${t('Try the application in three steps. There is no need for a polished pitch or a complete business plan.','用三个步骤体验申请。无需精美的提案，也不需要完整的商业计划。')}</p><p class="micro">${t('Prototype only. Nothing is sent to TRIIBE. Your draft stays in this browser; download it to keep a copy. Use a nickname and avoid sensitive information.','仅供原型测试，内容不会发送给 TRIIBE。草稿仅保存在此浏览器，可下载留存。请使用昵称，避免填写敏感信息。')}</p><button class="lang" id="clearDraft">${t('Clear saved draft','清除已存草稿')}</button></div><div class="formbox" id="formbox"></div></div></section>
<div class="wrap"><section id="faq"><div class="eyebrow">${t('A FEW THINGS TO KNOW','你可能想了解')}</div><h2>${t('Questions are a good start.','从问题开始，也很好。')}</h2>${[[t('Is this program accepting real applications?','现在可以正式申请吗？'),t('No. This is a student-developed concept prototype for research with TRIIBE. You can try the flow and download a practice application, but there is no live funding round or confirmed award.','目前不可以。这是围绕 TRIIBE 项目开发的学生研究原型。你可以体验流程并下载练习申请，但尚未开放真实资助，也没有确定的资助承诺。')],[t('Do I need to have founded an organization?','需要已经创立组织吗？'),t('The concept is designed to explore support for people aged 18–25 in China with early social-impact ideas. Final eligibility would need to be agreed with TRIIBE and local partners.','本概念探索如何支持中国 18–25 岁、有早期公益想法的年轻人。最终参与资格需要与 TRIIBE 和本地合作方共同确定。')],[t('How much funding could I receive?','可以获得多少资金？'),t('¥1,000–5,000 is a proposed range to test, not a promise. We are researching appropriate budgets, the source of funds, selection and the role of local partners.','¥1,000–5,000 是待测试的拟定范围，并非承诺。具体预算、资金来源、筛选方式和本地伙伴职责仍在研究中。')],[t('What if my idea does not work?','如果尝试没有成功怎么办？'),t('The proposed approach values learning. A pilot may lead to refining, continuing, scaling or stopping. You would document what happened and what you learned.','本方案重视学习。试点后可以调整、继续、扩大或暂停，关键是记录实际发生了什么，以及学到了什么。')],[t('What happens to my information?','填写的信息会保存在哪里？'),t('Drafts are saved locally in this browser only. There is no account or shared database. Use Clear saved draft to remove the application, and save the downloaded file yourself if you need it.','草稿仅保存在当前浏览器，没有账号或共享数据库。点击“清除已存草稿”即可删除申请；如需保留，请自行保存下载文件。')]].map(a=>`<details><summary>${a[0]}</summary><p>${a[1]}</p></details>`).join('')}</section></div></main><footer><div><a href="#" class="brand">TRIIBE <small>×</small> 联劝<span>THE NEXT STEP · 合作概念</span></a><p>${t('TRIIBE × Shanghai United Foundation / proposed collaboration','TRIIBE × 上海联劝公益基金会 / 拟议合作概念')}</p></div><div>${t('Developed for stakeholder research · 2026','用于利益相关者研究 · 2026')}<br>${t('Proposed features are subject to testing and partner agreement.','拟定功能仍需测试并与合作方确认。')}<br><a href="#apply">${t('Explore your idea ↑','体验申请 ↑')}</a></div></footer>`;
document.getElementById('language').onclick=()=>{capture();lang=lang==='en'?'zh':'en';localStorage.setItem('triibe-language',lang);render()};document.getElementById('clearDraft').onclick=()=>{draft={};step=1;quizStep=0;answers=[];try{localStorage.removeItem('triibe-draft')}catch{}renderForm()};document.querySelector('main').insertAdjacentHTML('beforeend',`<div class="wrap"><section id="partners"><div class="eyebrow">${t('A PROPOSED COLLABORATION','拟议合作构想')}</div><h2>${t('Global perspective.<br>Local understanding.','国际视野，<br>本地理解。')}</h2><p class="lead">${t('Exploring a shared support model for young people taking their first step in social impact.','探索共同支持年轻人迈出公益第一步的协作模式。')}</p><div class="partner-grid"><article class="partner-card"><span class="eyebrow">01 / TRIIBE</span><h3>${t('Support the emerging leader.','支持成长中的青年行动者。')}</h3><p>${t('Proposed role: contribute a youth leadership lens, pilot-learning tools and mentor connections, subject to agreement.','拟议职责：提供青年领导力视角、试点学习工具及导师资源连接，具体安排需双方确认。')}</p></article><article class="partner-card"><span class="eyebrow">02 / 上海联劝公益基金会</span><h3>${t('Connect the local context.','连接本地公益生态。')}</h3><p>${t('Proposed role: explore local needs, potential community connections and feasible delivery arrangements. No role or funding commitment has been confirmed.','拟议职责：共同探索本地需求、潜在社区连接与可行的执行安排。目前尚未确认任何职责或资助承诺。')}</p></article></div><div class="collab-note">${t('This page describes a student-designed partnership scenario. It does not represent endorsement, an existing agreement or an official program of either organization.','此页面呈现学生设计的合作情境，不代表任何一方的背书、已达成的合作协议或正式项目。')}</div><div class="actions"><a class="pill" href="#how">${t('Explore the proposed journey →','了解拟议参与流程 →')}</a></div></section></div>`);enhancePages();addUpdates();addVisuals();mergeJourney();improveBudgets();separateTools();renderForm();showPage();document.getElementById('menuToggle').onclick=()=>{const nav=document.getElementById('mainNav');const open=nav.classList.toggle('open');document.getElementById('menuToggle').setAttribute('aria-expanded',String(open))}}
const qs=()=>[{q:t('Where are you with your idea?','你的想法进行到哪一步了？'),a:[t('I care about an issue, but my idea is still forming.','我关心一个问题，但想法还在形成。'),t('I have an idea, but have not tried it yet.','我有想法，但还没开始。'),t('I have already tried something small.','我已经做过小型尝试。')]},{q:t('What is the biggest thing holding you back?','目前最阻碍你开始的是什么？'),a:[t('I am unsure what to do first.','我不确定第一步该做什么。'),t('I do not know the right people or local organizations.','我不认识合适的人或本地机构。'),t('I’m concerned about project costs.','担心项目费用。')]},{q:t('What would you like to accomplish next?','下一步你最想完成什么？'),a:[t('Turn my idea into a realistic plan.','把想法变成可执行的计划。'),t('Talk with people who understand the issue.','和了解这个问题的人交流。'),t('Run a small pilot and learn from it.','开展一次小型试点并学习。')]}];
function renderQuiz(){const box=document.getElementById('quiz');if(quizStep<3){const q=qs()[quizStep];box.innerHTML=`<p class="micro">${quizStep+1} / 3</p><h3>${q.q}</h3><div class="choices">${q.a.map((a,i)=>`<button class="choice" data-answer="${i}">${a} ↗</button>`).join('')}</div>${quizStep?`<button class="lang" id="qback" style="margin-top:20px">${t('← Back','← 上一步')}</button>`:''}`;box.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[quizStep]=Number(b.dataset.answer);quizStep++;renderQuiz()});if(quizStep)document.getElementById('qback').onclick=()=>{quizStep--;renderQuiz()}}else{const n=answers[1];recommendation=['Guidance','Connections','Seed support'][n];box.innerHTML=`<div class="eyebrow">${t('A POSSIBLE FIRST STEP','建议的第一步')}</div><div class="result"><h3>${[t('Start with guidance','先获得指导'),t('Start with a local connection','先建立本地联系'),t('Start with a pilot budget','先制定试点预算')][n]}</h3><p>${[t('Outline one small action and who it will help. A mentor conversation could help you narrow your idea before committing resources.','先明确一个小行动，以及它能帮助谁。与导师交流可以帮助你在投入资源前缩小范围。'),t('Identify one relevant community group and prepare a few questions. Understanding their needs can help you shape a useful pilot.','找到一个相关社区组织，准备几个问题。先了解对方的需求，再设计有用的试点。'),t('List the essential expenses for one small test. The proposed seed support could be relevant; funding is not currently available.','列出一次小型测试的必要开支。种子支持可能适合你，但目前尚无开放的真实资助。')][n]}</p></div><a href="#apply" class="pill" id="useSupport">${t('Use this in my application ↗','带着这个建议体验申请 ↗')}</a><p><button class="lang" id="qreset">${t('Start again','重新回答')}</button></p>`;document.getElementById('qreset').onclick=()=>{quizStep=0;answers=[];renderQuiz()};document.getElementById('useSupport').onclick=()=>{capture();draft.support=recommendation;save();renderForm()}}}
function save(){try{localStorage.setItem('triibe-draft',JSON.stringify(draft))}catch{}}function capture(){const form=document.getElementById('application');if(form)new FormData(form).forEach((v,k)=>draft[k]=v);save()}
function field(name,label,type='text',required=true){return `<label>${label}${required?' *':''}${type==='textarea'?`<textarea name="${name}" ${required?'required':''} maxlength="2000">${esc(draft[name])}</textarea>`:`<input name="${name}" type="${type}" value="${esc(draft[name])}" ${required?'required':''} ${type==='number'?'min="18" max="25" step="1"':'maxlength="150"'}>`}</label>`}
function timeline(){return `<div class="response-plan"><span class="eyebrow">${t('AFTER APPLYING / PROPOSED TARGETS','提交之后 / 拟议时间安排')}</span><div class="response-grid">${[[t('Immediately','提交后即时'),t('Confirmation + copy','确认申请并留存副本')],[t('Within 5 working days','5 个工作日内'),t('Initial review & update','初审并回复进度')],[t('Within 10 working days','10 个工作日内'),t('Short conversation if needed','如有需要，进行简短沟通')],[t('Within 15 working days','15 个工作日内'),t('Decision or revised timeline','告知结果或更新预计时间')]].map(a=>`<div><b>${a[0]}</b><p>${a[1]}</p></div>`).join('')}</div><p class="micro">${t('Proposed service targets, subject to partner agreement. This prototype stores your practice application locally and does not send it or trigger a reply.','以上为待合作方确认的目标时限。本原型仅在本地保存练习申请，不会实际发送或触发回复。')}</p></div>`}
function selectField(name,label,options){return `<label>${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${draft[name]===v?'selected':''}>${l}</option>`).join('')}</select></label>`}
function renderForm(){const box=document.getElementById('formbox');
 if(step===2){box.innerHTML=`<div class="success"><div class="eyebrow">${t('PRACTICE APPLICATION COMPLETE','练习申请完成')}</div><h3>${t('Your first step is ready.','你的第一步，准备好了。')}</h3><p>${t('Saved on this device only. Nothing has been sent.','仅保存在此设备，尚未实际发送。')}</p><div class="actions"><button class="pill" id="download">${t('Download a copy ↓','下载申请副本 ↓')}</button><button class="pill outline" id="edit">${t('Edit','修改')}</button></div>${timeline()}</div>`;document.getElementById('download').onclick=download;document.getElementById('edit').onclick=()=>{step=1;renderForm()};return}
 if(step===0){step=1}if(false){box.innerHTML=`<div class="eyebrow">${t('01 / A FEW QUICK CHOICES','01 / 先做几个简单选择')}</div><p class="micro">${t('No writing needed. Your choices carry into the application.','不用写文字，答案会自动带入申请。')}</p><div id="intakeQuiz"></div>`;renderIntake();return}
 box.innerHTML=`<div class="eyebrow">${t('YOUR SHORT APPLICATION','简短申请')}</div><p class="micro">${t('One short answer. No business plan or detailed budget needed.','只需一个简短回答，无需商业计划或详细预算。')}</p><p class="micro">${t('Tools are optional. Apply directly with a short idea.','需求推荐与预算估算为可选工具，可以直接用简短想法体验申请。')}</p><form id="application"><div class="row">${field('nickname',t('Nickname','昵称'))}${selectField('age',t('Age','年龄'),Array.from({length:8},(_,i)=>[String(i+18),String(i+18)]))}</div>${field('location',t('City / region','城市 / 地区'))}<label>${t('What do you want to try, and who is it for?','你想尝试什么？想帮助谁？')} *<textarea name="idea" required maxlength="300" placeholder="${t('A sentence or two is enough.','一两句话就好。')}">${esc(draft.idea)}</textarea></label><div class="row">${selectField('budget',t('Funding needed','希望申请的资助'),[['Unsure',t('Not sure yet','还不确定')],['1000','¥1,000'],['2000','¥2,000'],['3000','¥3,000'],['5000','¥5,000'],['0',t('Guidance only for now','暂时只需要指导')]])}${selectField('mentor',t('Mentor preference','导师偏好'),[['Either',t('Either is fine','都可以')],['China',t('China-based mentor','中国导师')],['International',t('International mentor','国际导师')]])}</div>${selectField('language',t('Preferred guidance language','指导语言偏好'),[['Chinese',t('Chinese','中文')],['English',t('English','英文')],['Either',t('Either / bilingual','都可以／双语')]])}<p class="micro">${t('Mentor profiles and availability are proposed. Your preference helps matching; no specific mentor is guaranteed.','导师配置与可用性尚待确认，偏好用于匹配，不保证特定导师。')}</p><label class="check"><input type="checkbox" name="ack" required ${draft.ack?'checked':''}><span>${t('I understand this is a local practice application, not a live funding request.','我理解这是本地练习申请，并非真实资助申请。')}</span></label><div class="formbuttons"><a class="lang" href="#find">${t('Support recommendation','需求推荐')}</a><button class="pill" type="submit">${t('Finish practice application ↗','完成练习申请 ↗')}</button></div></form>`;
 const form=document.getElementById('application');form.oninput=capture;form.onsubmit=e=>{e.preventDefault();capture();step=2;renderForm()};}
function renderIntake(){const box=document.getElementById('intakeQuiz');if(quizStep<3){const q=qs()[quizStep];box.innerHTML=`<p class="micro">${quizStep+1} / 3</p><h3>${q.q}</h3><div class="choices">${q.a.map((a,i)=>`<button class="choice" data-pick="${i}">${a} ↗</button>`).join('')}</div>${quizStep?`<button class="lang" id="intakeBack">${t('← Back','← 上一题')}</button>`:''}`;box.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{answers[quizStep]=Number(b.dataset.pick);quizStep++;renderIntake()});if(quizStep)document.getElementById('intakeBack').onclick=()=>{quizStep--;renderIntake()};return}
 recommendation=['Guidance','Connections','Seed support'][answers[1]];draft.stage=['Exploring','Idea','Pilot'][answers[0]];draft.support=recommendation;draft.nextGoal=['Plan','Conversation','Pilot'][answers[2]];save();box.innerHTML=`<h3>${[t('Start with guidance','先获得指导'),t('Start with a local connection','先建立本地联系'),t('Start with seed support','先探索种子资助')][answers[1]]}</h3><p>${t('We will use your choices in the short application. You can express your funding and mentor preferences next.','选择会自动带入申请，接下来只需补充简短想法、资助和导师偏好。')}</p><button class="pill" id="continueIntake">${t('Continue to short application →','继续填写简短申请 →')}</button>`;document.getElementById('continueIntake').onclick=()=>{step=1;renderForm()};}
function download(){const body='TRIIBE — Impact Seed Program\nPRACTICE APPLICATION / 练习申请\nNot submitted. No funding commitment. / 未提交，无资助承诺。\n\n'+Object.entries(draft).filter(([k])=>k!=='ack').map(([k,v])=>k+': '+v).join('\n\n');const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='TRIIBE-practice-application.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showPage(){
 document.body.classList.remove("page-enter"); void document.body.offsetWidth; document.body.classList.add("page-enter");
 const requested=(location.hash.slice(1)==='next'?'how':location.hash.slice(1))||'home';
 const page=['home','support','how','find','stories','partners','workflow','budget','contact','about','mentors','next','apply','faq'].includes(requested)?requested:'home';
 document.querySelectorAll('main section').forEach(el=>el.hidden=el.id!==page);
 document.querySelector('.hero').hidden=page!=='home';document.querySelector('.strip').hidden=page!=='home';
 document.querySelectorAll('main > .wrap').forEach(w=>w.hidden=![...w.children].some(el=>!el.hidden));
 document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(page==='find'&&a.dataset.nav==='support');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const nav=document.getElementById('mainNav');nav.classList.remove('open');document.getElementById('menuToggle').setAttribute('aria-expanded','false');
 window.scrollTo(0,0);if(requested==='how'&&location.hash==='#next')requestAnimationFrame(()=>document.getElementById('after-pilot')?.scrollIntoView({behavior:'smooth'}));
}
window.addEventListener('hashchange',()=>{capture();showPage()});render();

